-- LUCRA · questionários por link (PHQ-9 e GAD-7). Uma instrução por linha e pode rodar de novo.
create table if not exists public.questionarios (token uuid primary key default gen_random_uuid(), clinica_id uuid not null references public.clinicas(id) on delete cascade, cliente_id text not null default '', instrumento text not null check (instrumento in ('phq9','gad7')), respostas jsonb, pontos int, criado_em timestamptz not null default now(), respondido_em timestamptz);
create index if not exists questionarios_cid on public.questionarios(clinica_id);
alter table public.questionarios enable row level security;
drop policy if exists "clinico ve questionarios" on public.questionarios;
create policy "clinico ve questionarios" on public.questionarios for select to authenticated using (public.meu_papel(clinica_id) in ('dono','profissional'));
revoke all on public.questionarios from anon, authenticated;
grant select on public.questionarios to authenticated;
create or replace function public.criar_questionario(p_cid uuid, p_cliente text, p_instr text) returns uuid language plpgsql security definer set search_path = public as $$ declare t uuid; begin if meu_papel(p_cid) not in ('dono','profissional') or meu_papel(p_cid) is null then raise exception 'sem_acesso'; end if; insert into questionarios (clinica_id, cliente_id, instrumento) values (p_cid, left(coalesce(p_cliente, ''), 40), p_instr) returning token into t; return t; end $$;
create or replace function public.ver_questionario(p_token uuid) returns jsonb language sql stable security definer set search_path = public as $$ select jsonb_build_object('clinica', c.nome, 'area', c.area, 'instrumento', q.instrumento, 'respondido', q.respondido_em is not null) from questionarios q join clinicas c on c.id = q.clinica_id where q.token = p_token and q.criado_em > now() - interval '30 days' $$;
create or replace function public.responder_questionario(p_token uuid, p_respostas jsonb) returns text language plpgsql security definer set search_path = public as $$ declare q record; n int; tot int := 0; x jsonb; begin select * into q from questionarios where token = p_token and respondido_em is null and criado_em > now() - interval '30 days'; if q.token is null then raise exception 'invalido'; end if; n := case q.instrumento when 'phq9' then 9 else 7 end; if jsonb_typeof(p_respostas) <> 'array' or jsonb_array_length(p_respostas) <> n then raise exception 'respostas'; end if; for x in select * from jsonb_array_elements(p_respostas) loop if jsonb_typeof(x) <> 'number' or (x)::int < 0 or (x)::int > 3 then raise exception 'respostas'; end if; tot := tot + (x)::int; end loop; update questionarios set respostas = p_respostas, pontos = tot, respondido_em = now() where token = p_token; return 'ok'; end $$;
revoke execute on function public.criar_questionario(uuid, text, text) from public, anon;
grant execute on function public.criar_questionario(uuid, text, text) to authenticated;
grant execute on function public.ver_questionario(uuid), public.responder_questionario(uuid, jsonb) to anon, authenticated;
